//! Git-aware file walker.
//! Respects .gitignore exactly like `git` (via the `ignore` crate / `git ls-files`).
//! Also supports `.pttignore` for extra LLM-specific exclusions.

use crate::core::preview::resolve_under_canonical_root;
use ignore::WalkBuilder;
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::Arc;

/// Canonical list of junk / build-output directory names excluded from scans and presets.
pub const JUNK_DIRS: &[&str] = &[
    ".git",
    "node_modules",
    "target",
    "dist",
    "build",
    "out",
    ".vite",
    ".next",
    "coverage",
    "__pycache__",
    ".venv",
    ".turbo",
    ".cache",
    ".idea",
    ".vs",
    "vendor",
    "bin",
    "obj",
    "packages",
    "TestResults",
];

/// Returns true if `name` (a single directory component) is a known junk folder.
pub fn is_junk_dir_name(name: &str) -> bool {
    JUNK_DIRS
        .iter()
        .any(|&junk| junk.eq_ignore_ascii_case(name))
}

/// Lockfiles and generated manifests: unchecked by every preset (still visible in the tree).
pub const DEFAULT_EXCLUDED_FILE_NAMES: &[&str] = &[
    "package-lock.json",
    "pnpm-lock.yaml",
    "yarn.lock",
    "Cargo.lock",
    "composer.lock",
    "Gemfile.lock",
    "poetry.lock",
    "uv.lock",
];

/// Generated directories (relative, forward-slash, with trailing slash) excluded by presets.
pub const DEFAULT_EXCLUDED_DIR_PREFIXES: &[&str] = &["gen/schemas/"];

/// True when a relative path is a lockfile or generated schema that presets leave unchecked.
pub fn is_default_excluded_path(rel: &str) -> bool {
    let normalized = rel.replace('\\', "/");
    let name = normalized.rsplit('/').next().unwrap_or(&normalized);
    DEFAULT_EXCLUDED_FILE_NAMES.contains(&name)
        || DEFAULT_EXCLUDED_DIR_PREFIXES
            .iter()
            .any(|&p| normalized.starts_with(p))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DirEntryMeta {
    /// Relative path using forward slashes (LLM-friendly, cross-platform stable).
    pub path: PathBuf,
    pub is_dir: bool,
    pub size: Option<u64>,
}

/// Normalize a path to a relative, forward-slash form for stable UI + packing.
pub fn normalize_rel_path(path: &Path) -> String {
    let s = path.to_string_lossy();
    let s = s.strip_prefix("./").unwrap_or(&s);
    s.replace('\\', "/")
}

fn pathbuf_forward_slashes(path: &Path) -> PathBuf {
    PathBuf::from(normalize_rel_path(path))
}

/// Main entry point. Respects .gitignore + .pttignore.
pub fn walk(root: &Path) -> std::io::Result<Vec<DirEntryMeta>> {
    if !root.exists() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            format!("path does not exist: {}", root.display()),
        ));
    }
    if !root.is_dir() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            format!("path is not a directory: {}", root.display()),
        ));
    }

    let canonical_root = std::fs::canonicalize(root)?;

    // Prefer git ls-files for perfect fidelity when this is a git work tree.
    if let Ok(entries) = try_git_ls_files(&canonical_root) {
        return apply_pttignore_on_git_results(entries, &canonical_root);
    }

    walk_with_ignore(&canonical_root)
}

/// `git` command that never opens a console window. The GUI build of ptt has no
/// console, so on Windows each spawned child would otherwise flash a `cmd` window.
fn git_command() -> Command {
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        const CREATE_NO_WINDOW: u32 = 0x0800_0000;
        let mut cmd = Command::new("git");
        cmd.creation_flags(CREATE_NO_WINDOW);
        cmd
    }
    #[cfg(not(windows))]
    {
        Command::new("git")
    }
}

/// Fast path using actual git (best fidelity when available).
fn try_git_ls_files(root: &Path) -> Result<Vec<DirEntryMeta>, ()> {
    // Only use this path inside a git repository.
    let is_repo = git_command()
        .current_dir(root)
        .args(["rev-parse", "--is-inside-work-tree"])
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false);
    if !is_repo {
        return Err(());
    }

    let output = git_command()
        .current_dir(root)
        .args([
            "ls-files",
            "-z",
            "--cached",
            "--others",
            "--exclude-standard",
        ])
        .output();

    let output = match output {
        Ok(o) if o.status.success() => o,
        _ => return Err(()),
    };

    let mut entries = Vec::new();

    for part in output.stdout.split(|&b| b == 0) {
        if part.is_empty() {
            continue;
        }
        let rel_str = String::from_utf8_lossy(part);
        // Git always uses forward slashes in ls-files output.
        let rel_path = PathBuf::from(rel_str.replace('\\', "/"));

        let full = match resolve_under_canonical_root(root, &rel_str) {
            Ok(full) => full,
            Err(_) => continue,
        };
        // Skip entries that vanished between ls-files and stat. Symlinks are
        // skipped too: a tracked link can point at a file outside the project.
        match std::fs::symlink_metadata(&full) {
            Ok(m) if m.file_type().is_symlink() => continue,
            Ok(_) => {}
            Err(_) => continue,
        }
        let is_dir = full.is_dir();
        let size = if !is_dir {
            std::fs::metadata(&full).ok().map(|m| m.len())
        } else {
            None
        };

        entries.push(DirEntryMeta {
            path: rel_path,
            is_dir,
            size,
        });
    }

    Ok(entries)
}

/// Ensure directory entries exist for tree UI (git ls-files only lists files).
fn add_directory_entries(mut entries: Vec<DirEntryMeta>) -> Vec<DirEntryMeta> {
    let mut dir_paths: HashSet<PathBuf> = HashSet::new();
    for e in &entries {
        let mut current = e.path.parent();
        while let Some(p) = current {
            if p.as_os_str().is_empty() || p == Path::new(".") {
                break;
            }
            dir_paths.insert(pathbuf_forward_slashes(p));
            current = p.parent();
        }
    }
    let existing: HashSet<_> = entries.iter().map(|e| e.path.clone()).collect();
    for d in dir_paths {
        if !existing.contains(&d) {
            entries.push(DirEntryMeta {
                path: d,
                is_dir: true,
                size: None,
            });
        }
    }
    entries
}

/// Apply .pttignore on top of git results (additional exclusions for LLM packing).
fn apply_pttignore_on_git_results(
    entries: Vec<DirEntryMeta>,
    root: &Path,
) -> std::io::Result<Vec<DirEntryMeta>> {
    use ignore::gitignore::{Gitignore, GitignoreBuilder};
    type Rules = Vec<Arc<Gitignore>>;
    fn excluded(rules: &Rules, path: &Path, is_dir: bool) -> bool {
        rules
            .iter()
            .rev()
            .find_map(|rule| {
                let matched = rule.matched(path, is_dir);
                if matched.is_none() {
                    None
                } else {
                    Some(matched.is_ignore())
                }
            })
            .unwrap_or(false)
    }
    fn load_rules(root: &Path, directory: &Path, mut rules: Rules) -> std::io::Result<Rules> {
        let relative = directory.join(".pttignore");
        match resolve_under_canonical_root(root, &relative.to_string_lossy()) {
            Ok(path) => {
                let mut builder = GitignoreBuilder::new(root.join(directory));
                if let Some(error) = builder.add(&path) {
                    return Err(std::io::Error::new(std::io::ErrorKind::InvalidData, error));
                }
                rules.push(Arc::new(builder.build().map_err(|error| {
                    std::io::Error::new(std::io::ErrorKind::InvalidData, error)
                })?));
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error),
        }
        Ok(rules)
    }
    // Process directories top-down, just like a walker: an excluded parent cannot
    // be resurrected by a child rule. Each nested file has its own pattern root.
    let with_dirs = add_directory_entries(entries);
    let mut directories: Vec<_> = with_dirs
        .iter()
        .filter(|e| e.is_dir)
        .map(|e| e.path.clone())
        .collect();
    directories.sort_by_key(|path| path.components().count());
    let mut contexts: HashMap<PathBuf, (Rules, bool)> = HashMap::new();
    contexts.insert(
        PathBuf::new(),
        (load_rules(root, Path::new(""), Vec::new())?, false),
    );
    for directory in directories {
        let parent = directory.parent().unwrap_or(Path::new(""));
        let (rules, parent_excluded) = &contexts[parent];
        let blocked = *parent_excluded || excluded(rules, &root.join(&directory), true);
        let rules = if blocked {
            rules.clone()
        } else {
            load_rules(root, &directory, rules.clone())?
        };
        contexts.insert(directory, (rules, blocked));
    }
    let mut filtered: Vec<_> = with_dirs
        .into_iter()
        .filter(|entry| {
            if entry.is_dir {
                return !contexts[&entry.path].1;
            }
            let parent = entry.path.parent().unwrap_or(Path::new(""));
            let (rules, blocked) = &contexts[parent];
            !blocked && !excluded(rules, &root.join(&entry.path), false)
        })
        .collect();
    filtered.sort_by(|a, b| a.path.cmp(&b.path));
    Ok(filtered)
}

/// True when every failure belongs to a `.gitignore` file (parse or read error).
fn is_foreign_gitignore_error(error: &ignore::Error) -> bool {
    match error {
        ignore::Error::Partial(errors) => {
            !errors.is_empty() && errors.iter().all(is_foreign_gitignore_error)
        }
        ignore::Error::WithLineNumber { err, .. } | ignore::Error::WithDepth { err, .. } => {
            is_foreign_gitignore_error(err)
        }
        ignore::Error::WithPath { path, .. } => {
            path.file_name().is_some_and(|name| name == ".gitignore")
        }
        _ => false,
    }
}

/// Fallback using the ignore crate (gitignore + .pttignore).
fn walk_with_ignore(root: &Path) -> std::io::Result<Vec<DirEntryMeta>> {
    let mut builder = WalkBuilder::new(root);

    builder
        .standard_filters(true)
        .git_ignore(true)
        .git_exclude(true)
        .git_global(true)
        .require_git(false)
        .parents(true)
        .hidden(false)
        .ignore(false)
        .follow_links(false)
        .add_custom_ignore_filename(".pttignore");

    // Hard safety filters (junk that should never be included by default)
    builder.filter_entry(|entry| {
        if entry.file_type().is_some_and(|ft| ft.is_dir()) {
            if let Some(name) = entry.file_name().to_str() {
                if is_junk_dir_name(name) {
                    return false;
                }
            }
        }
        true
    });

    let walker = builder.build();
    let mut entries = Vec::new();

    for result in walker {
        let entry = match result {
            Ok(e) => e,
            Err(_) => continue,
        };

        // A broken line in a project's own .gitignore is skipped, as Git does.
        // Errors from .pttignore stay fail-closed: its rules must never be dropped silently.
        if let Some(error) = entry.error() {
            if !is_foreign_gitignore_error(error) {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    error.to_string(),
                ));
            }
        }
        let path = entry.path();

        if path != root
            && resolve_under_canonical_root(
                root,
                &path
                    .strip_prefix(root)
                    .map_err(std::io::Error::other)?
                    .to_string_lossy(),
            )
            .is_err()
        {
            continue;
        }

        let meta = match entry.metadata() {
            Ok(m) => m,
            Err(_) => continue,
        };

        let rel = path.strip_prefix(root).unwrap_or(path).to_path_buf();
        let rel = pathbuf_forward_slashes(&rel);

        // Skip the root itself
        if rel.as_os_str().is_empty() || rel == Path::new(".") {
            continue;
        }

        if meta.is_dir() {
            entries.push(DirEntryMeta {
                path: rel,
                is_dir: true,
                size: None,
            });
            continue;
        }

        if meta.is_file() {
            entries.push(DirEntryMeta {
                path: rel,
                is_dir: false,
                size: Some(meta.len()),
            });
        }
    }

    entries.sort_by(|a, b| a.path.cmp(&b.path));
    Ok(entries)
}

/// Selection is normalized once; each candidate checks only its own ancestors.
pub struct SelectionMatcher {
    paths: HashSet<String>,
}

impl SelectionMatcher {
    pub fn new(selected: &[String]) -> Self {
        Self {
            paths: selected
                .iter()
                .map(|path| {
                    normalize_rel_path(Path::new(path))
                        .trim_end_matches('/')
                        .to_owned()
                })
                .filter(|path| !path.is_empty())
                .collect(),
        }
    }

    pub fn is_selected(&self, candidate: &Path) -> bool {
        let normalized = normalize_rel_path(candidate);
        let mut prefix = normalized.as_str();
        loop {
            if self.paths.contains(prefix) {
                return true;
            }
            match prefix.rfind('/') {
                Some(index) => prefix = &prefix[..index],
                None => return false,
            }
        }
    }
}

/// Return true if `candidate` is the same path as `selected` or a descendant of it.
/// Paths are compared with forward-slash normalization.
pub fn path_is_selected(candidate: &Path, selected: &str) -> bool {
    let c = normalize_rel_path(candidate);
    let s = selected
        .replace('\\', "/")
        .trim_end_matches('/')
        .to_string();
    c == s || c.starts_with(&format!("{s}/"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::process::Command;

    fn init_git_repo(root: &Path) {
        let status = Command::new("git")
            .args(["init"])
            .current_dir(root)
            .status()
            .expect("git init");
        assert!(status.success());
        // Identity required on some CI images
        let _ = Command::new("git")
            .args(["config", "user.email", "ptt@test.local"])
            .current_dir(root)
            .status();
        let _ = Command::new("git")
            .args(["config", "user.name", "ptt-test"])
            .current_dir(root)
            .status();
    }

    #[test]
    fn normalize_rel_path_uses_forward_slashes() {
        assert_eq!(normalize_rel_path(Path::new("a\\b\\c")), "a/b/c");
        assert_eq!(
            normalize_rel_path(Path::new("./src/main.rs")),
            "src/main.rs"
        );
    }

    #[test]
    fn path_is_selected_matches_prefix() {
        assert!(path_is_selected(Path::new("src/main.rs"), "src"));
        assert!(path_is_selected(Path::new("src/main.rs"), "src/main.rs"));
        assert!(!path_is_selected(Path::new("src2/main.rs"), "src"));
    }

    #[test]
    fn walk_nonexistent_errors() {
        let err = walk(Path::new("/this/path/does/not/exist/ptt-xyz")).unwrap_err();
        assert_eq!(err.kind(), std::io::ErrorKind::NotFound);
    }

    #[test]
    fn walk_respects_gitignore_via_git() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        init_git_repo(root);

        fs::write(root.join("keep.rs"), "ok").unwrap();
        fs::write(root.join("secret.env"), "KEY=1").unwrap();
        fs::write(root.join(".gitignore"), "secret.env\n").unwrap();

        // Stage keep.rs so ls-files --cached sees it; untracked keep would also
        // appear via --others, but ignored secret.env must not.
        let _ = Command::new("git")
            .args(["add", "keep.rs", ".gitignore"])
            .current_dir(root)
            .status();

        let entries = walk(root).expect("walk");
        let paths: Vec<String> = entries
            .iter()
            .filter(|e| !e.is_dir)
            .map(|e| normalize_rel_path(&e.path))
            .collect();

        assert!(paths.iter().any(|p| p == "keep.rs"), "paths={paths:?}");
        assert!(
            !paths.iter().any(|p| p == "secret.env"),
            "secret.env must be ignored, got {paths:?}"
        );
    }

    #[cfg(unix)]
    #[test]
    fn walk_skips_tracked_symlinks_pointing_outside_repo() {
        let outside = tempfile::tempdir().unwrap();
        let secret = outside.path().join("id_rsa");
        fs::write(&secret, "PRIVATE").unwrap();

        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        init_git_repo(root);
        fs::write(root.join("keep.rs"), "ok").unwrap();
        std::os::unix::fs::symlink(&secret, root.join("link")).unwrap();

        let _ = Command::new("git")
            .args(["add", "-A"])
            .current_dir(root)
            .status();

        let entries = walk(root).expect("walk");
        let paths: Vec<String> = entries
            .iter()
            .filter(|e| !e.is_dir)
            .map(|e| normalize_rel_path(&e.path))
            .collect();

        assert!(paths.iter().any(|p| p == "keep.rs"), "paths={paths:?}");
        assert!(
            !paths.iter().any(|p| p == "link"),
            "symlink must be skipped, got {paths:?}"
        );
    }

    #[test]
    fn walk_applies_pttignore() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        init_git_repo(root);

        fs::write(root.join("app.rs"), "ok").unwrap();
        fs::write(root.join("noise.log"), "log").unwrap();
        fs::write(root.join(".pttignore"), "*.log\n").unwrap();

        let _ = Command::new("git")
            .args(["add", "-A"])
            .current_dir(root)
            .status();

        let entries = walk(root).expect("walk");
        let paths: Vec<String> = entries
            .iter()
            .filter(|e| !e.is_dir)
            .map(|e| normalize_rel_path(&e.path))
            .collect();

        assert!(paths.iter().any(|p| p == "app.rs"), "paths={paths:?}");
        assert!(
            !paths.iter().any(|p| p.ends_with("noise.log")),
            ".pttignore should drop noise.log, got {paths:?}"
        );
    }

    #[test]
    fn walk_without_git_still_works() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        fs::create_dir(root.join("src")).unwrap();
        fs::write(root.join("src/lib.rs"), "pub fn x() {}").unwrap();
        fs::write(root.join("README.md"), "# hi").unwrap();

        let entries = walk(root).expect("walk");
        let files: Vec<_> = entries.iter().filter(|e| !e.is_dir).collect();
        assert!(files.len() >= 2);
        assert!(files
            .iter()
            .any(|e| normalize_rel_path(&e.path) == "src/lib.rs"));
    }

    #[test]
    fn default_excluded_paths_cover_lockfiles_and_generated_schemas() {
        assert!(is_default_excluded_path("ui/package-lock.json"));
        assert!(is_default_excluded_path("Cargo.lock"));
        assert!(is_default_excluded_path("gen/schemas/desktop-schema.json"));
        assert!(!is_default_excluded_path("src/main.rs"));
        assert!(!is_default_excluded_path("docs/gen/schemas-notes.md"));
    }

    #[test]
    fn add_directory_entries_fills_parents() {
        let entries = vec![DirEntryMeta {
            path: PathBuf::from("a/b/c.rs"),
            is_dir: false,
            size: Some(1),
        }];
        let with = add_directory_entries(entries);
        let dirs: Vec<_> = with
            .iter()
            .filter(|e| e.is_dir)
            .map(|e| normalize_rel_path(&e.path))
            .collect();
        assert!(dirs.contains(&"a".to_string()));
        assert!(dirs.contains(&"a/b".to_string()));
    }
}


/**
 * Browser-mode project loading when Tauri IPC is unavailable
 * (e.g. opening Vite at http://localhost:5173 without `cargo tauri dev`).
 *
 * Uses the File System Access API (`showDirectoryPicker`) when available,
 * with a hidden <input webkitdirectory> fallback.
 */

import { redactSecrets, redactSecretsWithReport, type RedactionSummary } from './secrets';

export interface BrowserFileNode {
  path: string;
  name: string;
  is_dir: boolean;
  size?: number;
  selected: boolean;
}

export const CANONICAL_JUNK_DIRS = [
  '.git',
  'node_modules',
  'target',
  'dist',
  'build',
  'out',
  '.vite',
  '.next',
  'coverage',
  '__pycache__',
  '.venv',
  '.turbo',
  '.cache',
  '.idea',
  '.vs',
  'vendor',
  'bin',
  'obj',
  'packages',
  'TestResults',
] as const;

const JUNK_DIR_NAMES = new Set(CANONICAL_JUNK_DIRS.map((d) => d.toLowerCase()));

export type BrowserFileMap = Map<string, File>;

export interface BrowserSkippedItem {
  path: string;
  reason: 'junk_dir' | 'gitignore' | 'pttignore' | 'unreadable';
  detail?: string;
}

export interface BrowserProject {
  rootName: string;
  /** Relative POSIX paths → File blobs */
  files: BrowserFileMap;
  /** Items excluded or skipped during the browser scan */
  skipped?: BrowserSkippedItem[];
}

interface CompiledIgnoreRule {
  negated: boolean;
  dirOnly: boolean;
  baseDir: string;
  matcher: RegExp;
}

function globToRegExpSource(pattern: string): string {
  let out = '';
  let i = 0;
  while (i < pattern.length) {
    const ch = pattern[i];
    if (ch === '\\') {
      if (i + 1 >= pattern.length) {
        throw new Error('Trailing backslash in ignore pattern');
      }
      const next = pattern[i + 1];
      out += next.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      i += 2;
      continue;
    }
    if (ch === '*') {
      if (pattern[i + 1] === '*') {
        if (pattern[i + 2] === '/') {
          out += '(?:.*/)?';
          i += 3;
        } else {
          out += '.*';
          i += 2;
        }
      } else {
        out += '[^/]*';
        i += 1;
      }
      continue;
    }
    if (ch === '?') {
      out += '[^/]';
      i += 1;
      continue;
    }
    if (ch === '[') {
      const close = pattern.indexOf(']', i + 1);
      if (close === -1) {
        throw new Error('Unclosed character class in ignore pattern');
      }
      let cls = pattern.slice(i + 1, close);
      if (cls.startsWith('!')) cls = '^' + cls.slice(1);
      out += `[${cls}]`;
      i = close + 1;
      continue;
    }
    out += ch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    i += 1;
  }
  return out;
}

/**
 * Parses `.gitignore` or `.pttignore` text into compiled rules scoped to `baseDir`.
 * When `strict` is true (`.pttignore`), invalid syntax throws an error (fail-closed),
 * matching Rust `apply_pttignore_on_git_results` / `walk_with_ignore`.
 */
export function parseIgnoreFile(
  content: string,
  baseDir: string,
  strict: boolean,
): CompiledIgnoreRule[] {
  const rules: CompiledIgnoreRule[] = [];
  const lines = content.split(/\r?\n/);
  for (const rawLine of lines) {
    let line = rawLine;
    // Strip unescaped trailing spaces
    while (line.endsWith(' ') && !line.endsWith('\\ ')) {
      line = line.slice(0, -1);
    }
    if (!line || line.startsWith('#')) continue;
    if (line.startsWith('\\#') || line.startsWith('\\!')) {
      line = line.slice(1);
    } else if (line.startsWith('!')) {
      const rest = line.slice(1);
      if (!rest) {
        if (strict) throw new Error('Invalid empty negation pattern "!" in .pttignore');
        continue;
      }
      try {
        rules.push(compileSingleRule(rest, baseDir, true, strict));
      } catch (err) {
        if (strict) throw err;
      }
      continue;
    }
    try {
      rules.push(compileSingleRule(line, baseDir, false, strict));
    } catch (err) {
      if (strict) throw err;
    }
  }
  return rules;
}

function compileSingleRule(
  rawPattern: string,
  baseDir: string,
  negated: boolean,
  strict: boolean,
): CompiledIgnoreRule {
  let pat = rawPattern;
  const dirOnly = pat.endsWith('/');
  if (dirOnly) pat = pat.replace(/\/+$/, '');
  if (!pat) {
    throw new Error('Empty ignore pattern');
  }
  // Reject invalid `**` adjacency in strict mode (e.g. `a/**b`)
  if (strict && /(?<!^|\/)\*\*|\*\*(?!$|\/)/.test(pat)) {
    throw new Error(`Invalid globstar placement in .pttignore: ${rawPattern}`);
  }
  const leadingSlash = pat.startsWith('/');
  if (leadingSlash) pat = pat.slice(1);
  const anchored = leadingSlash || pat.includes('/');
  const regexBody = globToRegExpSource(pat);
  const fullRegexStr = anchored ? `^${regexBody}$` : `(?:^|/)${regexBody}$`;
  const matcher = new RegExp(fullRegexStr);
  return { negated, dirOnly, baseDir, matcher };
}

function evaluateIgnoreRules(
  rules: readonly CompiledIgnoreRule[],
  relPath: string,
  isDir: boolean,
): boolean {
  let ignored = false;
  for (const rule of rules) {
    if (rule.dirOnly && !isDir) continue;
    let subPath = relPath;
    if (rule.baseDir) {
      const prefix = `${rule.baseDir}/`;
      if (!relPath.startsWith(prefix)) continue;
      subPath = relPath.slice(prefix.length);
    }
    if (rule.matcher.test(subPath)) {
      ignored = !rule.negated;
    }
  }
  return ignored;
}

export class UserCancelledError extends Error {
  constructor(message = 'User cancelled folder selection') {
    super(message);
    this.name = 'UserCancelledError';
  }
}

function isJunkDir(name: string): boolean {
  return JUNK_DIR_NAMES.has(name.toLowerCase());
}

function isCancelledError(e: unknown): boolean {
  if (e instanceof UserCancelledError) return true;
  if (e instanceof DOMException && (e.name === 'AbortError' || e.name === 'NotAllowedError')) {
    // NotAllowedError can mean user dismissed in some browsers
    return e.name === 'AbortError';
  }
  const msg = e instanceof Error ? e.message : String(e);
  return /abort|cancel/i.test(msg);
}

/** Iterate directory entries across browser implementations. */
async function* directoryEntries(
  dir: FileSystemDirectoryHandle,
): AsyncGenerator<[string, FileSystemHandle]> {
  const anyDir = dir as FileSystemDirectoryHandle & {
    entries?: () => AsyncIterableIterator<[string, FileSystemHandle]>;
    values?: () => AsyncIterableIterator<FileSystemHandle>;
  };

  if (typeof anyDir.entries === 'function') {
    for await (const entry of anyDir.entries()) {
      yield entry;
    }
    return;
  }

  if (typeof anyDir.values === 'function') {
    for await (const handle of anyDir.values()) {
      yield [handle.name, handle];
    }
    return;
  }

  throw new Error('This browser cannot list folder contents (File System Access incomplete).');
}

/**
 * Applies top-down `.gitignore` and `.pttignore` pruning and filtering to an arbitrary
 * candidate map of `relPath -> File`. Mirrors Rust `apply_pttignore_on_git_results` /
 * `walk_with_ignore`:
 * - Excluded parent directories cannot be resurrected by child negation rules.
 * - `.pttignore` syntax/read errors fail closed (throw), whereas `.gitignore` syntax errors
 *   skip only the offending line.
 */
export async function applyIgnoreSemanticsToFileMap(
  rawFiles: BrowserFileMap,
  initialSkipped: BrowserSkippedItem[] = [],
): Promise<{
  files: BrowserFileMap;
  dirPaths: Set<string>;
  skipped: BrowserSkippedItem[];
}> {
  const skipped: BrowserSkippedItem[] = [...initialSkipped];
  const allDirs = new Set<string>();
  for (const rel of rawFiles.keys()) {
    const segs = rel.split('/');
    let acc = '';
    for (let i = 0; i < segs.length - 1; i++) {
      acc = acc ? `${acc}/${segs[i]}` : segs[i];
      allDirs.add(acc);
    }
  }

  const sortedDirs = ['', ...Array.from(allDirs).sort((a, b) => a.split('/').length - b.split('/').length || a.localeCompare(b))];

  interface DirIgnoreContext {
    gitRules: CompiledIgnoreRule[];
    pttRules: CompiledIgnoreRule[];
    blockedBy: 'gitignore' | 'pttignore' | null;
  }

  const contexts = new Map<string, DirIgnoreContext>();

  async function loadRulesForDir(
    dir: string,
    parentGit: CompiledIgnoreRule[],
    parentPtt: CompiledIgnoreRule[],
  ): Promise<{ gitRules: CompiledIgnoreRule[]; pttRules: CompiledIgnoreRule[] }> {
    let gitRules = parentGit;
    let pttRules = parentPtt;
    const gitPath = dir ? `${dir}/.gitignore` : '.gitignore';
    const pttPath = dir ? `${dir}/.pttignore` : '.pttignore';

    const gitFile = rawFiles.get(gitPath);
    if (gitFile) {
      try {
        const text = await gitFile.text();
        gitRules = [...parentGit, ...parseIgnoreFile(text, dir, false)];
      } catch {
        // Foreign .gitignore read errors do not abort the walk
      }
    }

    const pttFile = rawFiles.get(pttPath);
    if (pttFile) {
      const text = await pttFile.text();
      pttRules = [...parentPtt, ...parseIgnoreFile(text, dir, true)];
    }

    return { gitRules, pttRules };
  }

  const rootLoaded = await loadRulesForDir('', [], []);
  contexts.set('', { ...rootLoaded, blockedBy: null });

  for (const dir of sortedDirs) {
    if (dir === '') continue;
    const slash = dir.lastIndexOf('/');
    const parent = slash < 0 ? '' : dir.slice(0, slash);
    const parentCtx = contexts.get(parent)!;

    if (parentCtx.blockedBy) {
      contexts.set(dir, {
        gitRules: parentCtx.gitRules,
        pttRules: parentCtx.pttRules,
        blockedBy: parentCtx.blockedBy,
      });
      continue;
    }

    const blockedByGit = evaluateIgnoreRules(parentCtx.gitRules, dir, true);
    const blockedByPtt = !blockedByGit && evaluateIgnoreRules(parentCtx.pttRules, dir, true);
    const blockedBy = blockedByGit ? 'gitignore' : blockedByPtt ? 'pttignore' : null;
    if (blockedBy) {
      skipped.push({ path: dir, reason: blockedBy });
      contexts.set(dir, {
        gitRules: parentCtx.gitRules,
        pttRules: parentCtx.pttRules,
        blockedBy,
      });
    } else {
      const loaded = await loadRulesForDir(dir, parentCtx.gitRules, parentCtx.pttRules);
      contexts.set(dir, { ...loaded, blockedBy: null });
    }
  }

  const keptFiles: BrowserFileMap = new Map();
  const keptDirs = new Set<string>();

  for (const [dir, ctx] of contexts.entries()) {
    if (dir !== '' && !ctx.blockedBy) {
      keptDirs.add(dir);
    }
  }

  for (const [rel, file] of rawFiles.entries()) {
    const slash = rel.lastIndexOf('/');
    const parent = slash < 0 ? '' : rel.slice(0, slash);
    const ctx = contexts.get(parent);
    if (!ctx || ctx.blockedBy) continue;

    if (evaluateIgnoreRules(ctx.gitRules, rel, false)) {
      skipped.push({ path: rel, reason: 'gitignore' });
      continue;
    }
    if (evaluateIgnoreRules(ctx.pttRules, rel, false)) {
      skipped.push({ path: rel, reason: 'pttignore' });
      continue;
    }
    keptFiles.set(rel, file);
  }

  return { files: keptFiles, dirPaths: keptDirs, skipped };
}

/** Recursively list a FileSystemDirectoryHandle into flat nodes + file map, honoring .gitignore and .pttignore. */
export async function scanDirectoryHandle(
  root: FileSystemDirectoryHandle,
): Promise<{ nodes: BrowserFileNode[]; project: BrowserProject }> {
  const rawFiles: BrowserFileMap = new Map();
  const skipped: BrowserSkippedItem[] = [];
  let fileCount = 0;
  const MAX_FILES = 25_000;

  async function walk(dir: FileSystemDirectoryHandle, prefix: string) {
    for await (const [name, handle] of directoryEntries(dir)) {
      if (!name || name === '.' || name === '..') continue;
      const rel = (prefix ? `${prefix}/${name}` : name).replace(/\\/g, '/');

      if (handle.kind === 'directory') {
        if (isJunkDir(name)) {
          skipped.push({ path: rel, reason: 'junk_dir' });
          continue;
        }
        await walk(handle as FileSystemDirectoryHandle, rel);
        continue;
      }

      if (handle.kind === 'file') {
        if (fileCount >= MAX_FILES) {
          throw new Error(
            `Folder is too large (>${MAX_FILES} files). Use cargo tauri dev for big projects, or open a smaller subfolder.`,
          );
        }
        try {
          const file = await (handle as FileSystemFileHandle).getFile();
          rawFiles.set(rel, file);
          fileCount++;
        } catch (err) {
          skipped.push({
            path: rel,
            reason: 'unreadable',
            detail: err instanceof Error ? err.message : String(err),
          });
          console.warn('Skip unreadable file', rel, err);
        }
      }
    }
  }

  await walk(root, '');

  const filtered = await applyIgnoreSemanticsToFileMap(rawFiles, skipped);
  const nodes: BrowserFileNode[] = [];
  for (const d of filtered.dirPaths) {
    nodes.push({
      path: d,
      name: d.split('/').pop() || d,
      is_dir: true,
      selected: false,
    });
  }
  for (const [path, file] of filtered.files) {
    nodes.push({
      path,
      name: path.split('/').pop() || path,
      is_dir: false,
      size: file.size,
      selected: false,
    });
  }
  nodes.sort((a, b) => a.path.localeCompare(b.path));

  return {
    nodes,
    project: {
      rootName: root.name || 'project',
      files: filtered.files,
      skipped: filtered.skipped,
    },
  };
}

/**
 * Scan files from a legacy <input webkitdirectory> FileList, honoring .gitignore and .pttignore.
 */
export async function scanFileList(list: FileList | File[]): Promise<{
  nodes: BrowserFileNode[];
  project: BrowserProject;
}> {
  const rawFiles: BrowserFileMap = new Map();
  const skipped: BrowserSkippedItem[] = [];
  let rootName = 'project';

  const arr = Array.from(list);
  for (const file of arr) {
    // webkitRelativePath like "MyApp/src/Main.cs"
    const relFull =
      (file as File & { webkitRelativePath?: string }).webkitRelativePath || file.name;
    const parts = relFull.replace(/\\/g, '/').split('/').filter(Boolean);
    if (parts.length === 0) continue;

    if (parts.length === 1) {
      rawFiles.set(parts[0], file);
      continue;
    }

    rootName = parts[0];

    // Skip junk intermediate folders
    let skip = false;
    for (let i = 1; i < parts.length - 1; i++) {
      if (isJunkDir(parts[i])) {
        skipped.push({ path: parts.slice(1, i + 1).join('/'), reason: 'junk_dir' });
        skip = true;
        break;
      }
    }
    if (skip) continue;

    const rel = parts.slice(1).join('/');
    rawFiles.set(rel, file);
  }

  const filtered = await applyIgnoreSemanticsToFileMap(rawFiles, skipped);
  const nodes: BrowserFileNode[] = [];
  for (const d of filtered.dirPaths) {
    nodes.push({
      path: d,
      name: d.split('/').pop() || d,
      is_dir: true,
      selected: false,
    });
  }
  for (const [path, file] of filtered.files) {
    nodes.push({
      path,
      name: path.split('/').pop() || path,
      is_dir: false,
      size: file.size,
      selected: false,
    });
  }
  nodes.sort((a, b) => a.path.localeCompare(b.path));

  return {
    nodes,
    project: {
      rootName,
      files: filtered.files,
      skipped: filtered.skipped,
    },
  };
}

/** Pick a directory via File System Access API (Chrome/Edge). */
export async function pickDirectoryWithPicker(): Promise<FileSystemDirectoryHandle> {
  const w = window as unknown as {
    showDirectoryPicker?: (opts?: { mode?: string }) => Promise<FileSystemDirectoryHandle>;
  };
  if (typeof w.showDirectoryPicker !== 'function') {
    throw new Error('SHOW_DIRECTORY_PICKER_UNSUPPORTED');
  }
  try {
    return await w.showDirectoryPicker({ mode: 'read' });
  } catch (e) {
    if (isCancelledError(e)) throw new UserCancelledError();
    throw e;
  }
}

/** Hidden webkitdirectory input fallback (Firefox/Safari). */
export function pickDirectoryWithInput(): Promise<FileList> {
  return new Promise((resolve, reject) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.multiple = true;
    input.setAttribute('webkitdirectory', '');
    input.setAttribute('directory', '');
    (input as HTMLInputElement & { webkitdirectory?: boolean }).webkitdirectory = true;
    input.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0;';

    let settled = false;
    const finish = (fn: () => void) => {
      if (settled) return;
      settled = true;
      window.removeEventListener('focus', onWindowFocus);
      input.remove();
      fn();
    };

    input.addEventListener('change', () => {
      const files = input.files;
      if (files && files.length > 0) {
        finish(() => resolve(files));
      } else {
        finish(() => reject(new UserCancelledError()));
      }
    });

    // Cancel detection: window regains focus and no change event fired
    const onWindowFocus = () => {
      window.setTimeout(() => {
        if (!settled && (!input.files || input.files.length === 0)) {
          finish(() => reject(new UserCancelledError()));
        }
      }, 800);
    };
    window.addEventListener('focus', onWindowFocus);

    document.body.appendChild(input);
    input.click();
  });
}

const PREVIEW_MAX = 512 * 1024;
const PACK_MAX = 2 * 1024 * 1024;

type DecodeResult = { ok: true; text: string } | { ok: false; reason: 'binary' | 'encoding' };

const INVALID_ENCODING_MESSAGE = '[Invalid text encoding: use UTF-8 or UTF-16 with BOM]';

/** Mirrors `decode_text` in src/core/text.rs: UTF-8 or BOM-declared UTF-16, never guessed. */
function decodeText(buf: Uint8Array, truncated = false): DecodeResult {
  const encoding = buf[0] === 0xff && buf[1] === 0xfe ? 'utf-16le'
    : buf[0] === 0xfe && buf[1] === 0xff ? 'utf-16be' : 'utf-8';
  const hasBom = encoding !== 'utf-8' || (buf[0] === 0xef && buf[1] === 0xbb && buf[2] === 0xbf);
  if (!hasBom && looksBinary(buf)) return { ok: false, reason: 'binary' };
  let text: string;
  try {
    text = new TextDecoder(encoding, { fatal: true }).decode(buf, { stream: truncated });
  } catch {
    return { ok: false, reason: 'encoding' };
  }
  return text.includes('\0') ? { ok: false, reason: 'binary' } : { ok: true, text };
}

function markdownFence(content: string): string {
  let longest = 0;
  let run = 0;
  for (const char of content) {
    run = char === '`' ? run + 1 : 0;
    longest = Math.max(longest, run);
  }
  return '`'.repeat(Math.max(3, longest + 1));
}

export async function readBrowserFilePreview(
  project: BrowserProject,
  relativePath: string,
): Promise<{
  path: string;
  relativePath: string;
  language: string;
  content: string;
  size: number;
  truncated: boolean;
  binary: boolean;
  absolutePath: string;
}> {
  const key = relativePath.replace(/\\/g, '/');
  const file = project.files.get(key);
  if (!file) throw new Error(`File not found: ${relativePath}`);
  const size = file.size;
  if (size === 0) {
    return {
      path: file.name,
      relativePath: key,
      language: guessLang(key),
      content: '',
      size: 0,
      truncated: false,
      binary: false,
      absolutePath: `${project.rootName}/${key}`,
    };
  }
  const slice = file.slice(0, Math.min(size, PREVIEW_MAX));
  const buf = new Uint8Array(await slice.arrayBuffer());
  const truncated = size > PREVIEW_MAX;
  const decoded = decodeText(buf, truncated);
  if (!decoded.ok && decoded.reason === 'encoding') {
    return {
      path: file.name,
      relativePath: key,
      language: 'plaintext',
      content: INVALID_ENCODING_MESSAGE,
      size,
      truncated: false,
      binary: false,
      absolutePath: `${project.rootName}/${key}`,
    };
  }
  if (!decoded.ok) {
    return {
      path: file.name,
      relativePath: key,
      language: 'plaintext',
      content: `[Binary file — ${size} bytes. Open with an external app to view.]`,
      size,
      truncated: false,
      binary: true,
      absolutePath: `${project.rootName}/${key}`,
    };
  }
  let content = decoded.text;
  if (truncated) {
    content += `\n\n// … truncated for preview (${size} bytes total) …`;
  }
  return {
    path: file.name,
    relativePath: key,
    language: guessLang(key),
    content,
    size,
    truncated,
    binary: false,
    absolutePath: `${project.rootName}/${key}`,
  };
}

function looksBinary(buf: Uint8Array): boolean {
  const n = Math.min(buf.length, 8000);
  let suspicious = 0;
  for (let i = 0; i < n; i++) {
    const b = buf[i];
    if (b === 0) return true;
    if (b < 7 || (b > 14 && b < 32 && b !== 9 && b !== 10 && b !== 13)) suspicious++;
  }
  return suspicious / n > 0.3;
}

function guessLang(path: string): string {
  const lower = path.toLowerCase();
  if (lower.endsWith('.xaml') || lower.endsWith('.csproj') || lower.endsWith('.xml')) return 'xml';
  if (lower.endsWith('.cs') || lower.endsWith('.xaml.cs')) return 'csharp';
  if (lower.endsWith('.ts') || lower.endsWith('.tsx')) return 'typescript';
  if (lower.endsWith('.js') || lower.endsWith('.jsx')) return 'javascript';
  if (lower.endsWith('.json')) return 'json';
  if (lower.endsWith('.rs')) return 'rust';
  if (lower.endsWith('.py')) return 'python';
  if (lower.endsWith('.md')) return 'markdown';
  if (lower.endsWith('.css') || lower.endsWith('.scss')) return 'css';
  if (lower.endsWith('.html') || lower.endsWith('.razor')) return 'xml';
  if (lower.endsWith('.yml') || lower.endsWith('.yaml')) return 'yaml';
  if (lower.endsWith('.toml')) return 'toml';
  if (lower.endsWith('.sh')) return 'bash';
  return 'plaintext';
}

function escapeXmlAttr(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

export interface BrowserGenerateOptions {
  redactSecrets?: boolean;
  skeletonFiles?: Set<string>;
  taskPrompt?: string;
}

function extractBrowserSkeleton(content: string): string {
  const lines = content.split('\n');
  const out: string[] = [];
  let braceDepth = 0;
  let elidedAt: number | null = null;

  for (const line of lines) {
    const trimmed = line.trim();
    const opens = (line.match(/\{/g) || []).length;
    const closes = (line.match(/\}/g) || []).length;

    if (elidedAt !== null) {
      braceDepth += opens - closes;
      if (braceDepth < elidedAt) {
        elidedAt = null;
      }
      continue;
    }

    const isType =
      /^(?:export\s+)?(?:interface|type|class|enum|struct|trait|impl|mod|namespace)\b/.test(
        trimmed,
      );
    const preDepth = braceDepth;
    braceDepth += opens - closes;

    if (opens > closes && preDepth >= 0 && !isType && trimmed.includes('(')) {
      const idx = line.lastIndexOf('{');
      if (idx !== -1) {
        out.push(`${line.slice(0, idx).trimEnd()} { /* ... */ }`);
        elidedAt = braceDepth;
        continue;
      }
    }
    out.push(line);
  }
  return out.join('\n');
}

async function readPackContentWithReport(
  file: File,
  doRedact = true,
  isSkeleton = false,
): Promise<{ content: string; summary: RedactionSummary }> {
  const skippedSummary: RedactionSummary = {
    totalRedactions: 0,
    kinds: [],
    redactionEnabled: doRedact,
    filesScanned: 0,
    filesSkipped: 1,
  };
  if (file.size > PACK_MAX) {
    return {
      content: `[File too large: ${file.size} bytes (limit ${PACK_MAX}), skipped]`,
      summary: skippedSummary,
    };
  }
  try {
    const buf = new Uint8Array(await file.arrayBuffer());
    const decoded = decodeText(buf);
    if (decoded.ok) {
      let text = decoded.text;
      let summary: RedactionSummary = {
        totalRedactions: 0,
        kinds: [],
        redactionEnabled: doRedact,
        filesScanned: doRedact ? 1 : 0,
        filesSkipped: 0,
      };
      if (doRedact) {
        const res = redactSecretsWithReport(text);
        text = res.text;
        summary = {
          ...res.summary,
          redactionEnabled: true,
          filesScanned: 1,
          filesSkipped: 0,
        };
      } else {
        // silence unused import if needed
        void redactSecrets;
      }
      if (isSkeleton) {
        text = extractBrowserSkeleton(text);
      }
      return { content: text, summary };
    }
    if (decoded.reason === 'encoding') {
      return { content: INVALID_ENCODING_MESSAGE, summary: skippedSummary };
    }
    return {
      content: `[Binary file - ${file.size} bytes, content omitted for LLM safety]`,
      summary: skippedSummary,
    };
  } catch (e) {
    return {
      content: `[Error reading file: ${e instanceof Error ? e.message : String(e)}]`,
      summary: skippedSummary,
    };
  }
}

/**
 * Architectural emission tier for `<files>` content (lower is emitted first). Mirrors
 * `architectural_tier` in src/core/output.rs: 0 source, 1 manifests, 2 tests/examples,
 * 3 docs, CI metadata and everything else.
 */
export function architecturalTier(path: string): number {
  const lower = path.replace(/\\/g, '/').toLowerCase();
  const name = lower.slice(lower.lastIndexOf('/') + 1);
  const inDir = (dir: string) => lower.startsWith(`${dir}/`) || lower.includes(`/${dir}/`);

  const manifests = [
    'cargo.toml',
    'package.json',
    'tauri.conf.json',
    'pyproject.toml',
    'go.mod',
    'makefile',
    'dockerfile',
    'build.rs',
  ];
  if (manifests.includes(name) || (name.startsWith('tsconfig') && name.endsWith('.json'))) {
    return 1;
  }

  const isTestName =
    name.includes('.test.') ||
    name.includes('.spec.') ||
    name.includes('_test.') ||
    name.startsWith('test_');
  if (isTestName || ['tests', 'e2e', 'examples', 'benches'].some(inDir)) {
    return 2;
  }

  const sourceExts = [
    '.rs', '.ts', '.tsx', '.js', '.jsx', '.py', '.go', '.cs', '.java', '.c', '.cpp', '.h', '.hpp',
  ];
  const isRootSource = !lower.includes('/') && sourceExts.some((e) => lower.endsWith(e));
  const sourceDirs = ['src', 'lib', 'app', 'pkg', 'cmd', 'internal', 'crates', 'packages'];
  if (isRootSource || sourceDirs.some(inDir)) {
    return 0;
  }

  return 3;
}

export async function generateBrowserOutputWithStats(
  project: BrowserProject,
  selectedPaths: string[],
  format: string,
  opts: BrowserGenerateOptions = {},
): Promise<{
  text: string;
  redactions: RedactionSummary;
  fileTokens: { path: string; bytes: number; tokens: number; mode: 'full' | 'skeleton' }[];
}> {
  const doRedact = opts.redactSecrets !== false;
  const skelSet = opts.skeletonFiles ?? new Set<string>();
  // The prompt is masked with the same rules as file contents when redaction is on (parity with
  // the native `task_prompt_text` in src/core/output.rs). Its counts are included in the report.
  const rawTaskPrompt = opts.taskPrompt?.trim() || '';
  const promptRedaction = doRedact && rawTaskPrompt ? redactSecretsWithReport(rawTaskPrompt) : null;
  const taskPrompt = promptRedaction ? promptRedaction.text : rawTaskPrompt;

  const selected = new Set(selectedPaths.map((p) => p.replace(/\\/g, '/').replace(/\/+$/, '')));
  const isSelected = (path: string): boolean => {
    let prefix = path;
    while (prefix) {
      if (selected.has(prefix)) return true;
      const slash = prefix.lastIndexOf('/');
      if (slash < 0) return false;
      prefix = prefix.slice(0, slash);
    }
    return false;
  };
  const entries: { path: string; file: File }[] = [];
  for (const [path, file] of project.files) {
    if (isSelected(path)) {
      entries.push({ path, file });
    }
  }
  entries.sort((a, b) => a.path.localeCompare(b.path));

  // Content is emitted by architectural tier (stable, so ties stay alphabetical). The file cap
  // applies after this ordering, so the cap drops docs and CI metadata before source code.
  const MAX_PACK_FILES = 400;
  const contentOrder = [...entries].sort((a, b) => architecturalTier(a.path) - architecturalTier(b.path));
  const limited = contentOrder.slice(0, MAX_PACK_FILES);
  const truncatedNote =
    entries.length > MAX_PACK_FILES
      ? `\n<!-- packed first ${MAX_PACK_FILES} of ${entries.length} selected files (browser limit) -->\n`
      : '';

  let totalRedactions = promptRedaction?.summary.totalRedactions ?? 0;
  let filesScanned = 0;
  let filesSkipped = 0;
  const kindMap = new Map<string, number>(promptRedaction?.summary.kinds ?? []);
  const fileTokens: { path: string; bytes: number; tokens: number; mode: 'full' | 'skeleton' }[] = [];

  const prepared: { path: string; size: number; content: string; isSkel: boolean }[] = [];
  for (const e of limited) {
    const isSkel = skelSet.has(e.path);
    const { content, summary } = await readPackContentWithReport(e.file, doRedact, isSkel);
    totalRedactions += summary.totalRedactions;
    filesScanned += summary.filesScanned ?? 0;
    filesSkipped += summary.filesSkipped ?? 0;
    for (const [k, c] of summary.kinds) {
      kindMap.set(k, (kindMap.get(k) ?? 0) + c);
    }
    const tokens = Math.max(0, Math.round(content.length / 3.8));
    fileTokens.push({
      path: e.path,
      bytes: content.length,
      tokens,
      mode: isSkel ? 'skeleton' : 'full',
    });
    prepared.push({ path: e.path, size: e.file.size, content, isSkel });
  }

  const redactions: RedactionSummary = {
    totalRedactions,
    kinds: Array.from(kindMap.entries()),
    redactionEnabled: doRedact,
    filesScanned,
    filesSkipped,
  };

  if (format === 'json') {
    const files = prepared.map((p) =>
      p.isSkel
        ? { path: p.path, size: p.size, mode: 'skeleton', content: p.content }
        : { path: p.path, size: p.size, content: p.content },
    );
    const doc: Record<string, unknown> = {
      generator: 'ptt (ProjectToText) browser-mode',
      root: project.rootName,
      file_count: files.length,
      files,
    };
    if (taskPrompt) doc.task_instructions = taskPrompt;
    return {
      text: JSON.stringify(doc, null, 2),
      redactions,
      fileTokens,
    };
  }

  if (format === 'markdown') {
    const parts = [
      `# Project Context`,
      `Generated from: \`${project.rootName}\` (browser mode)\n`,
      truncatedNote,
    ];
    for (const p of prepared) {
      const ext = p.path.includes('.') ? p.path.split('.').pop() : '';
      const fence = markdownFence(p.content);
      const header = p.isSkel ? `## \`${p.path}\` *(skeleton)*` : `## \`${p.path}\``;
      parts.push(`${header}\n${fence}${ext}\n${p.content}\n${fence}\n`);
    }
    if (taskPrompt) {
      parts.push(`<task_instructions>\n${taskPrompt}\n</task_instructions>`);
    }
    return { text: parts.join('\n'), redactions, fileTokens };
  }

  if (format === 'plain') {
    const parts = [
      `Project: ${project.rootName}`,
      '================================\n',
      truncatedNote,
    ];
    for (const p of prepared) {
      parts.push(
        p.isSkel ? `>>> ${p.path} [skeleton]` : `>>> ${p.path}`,
        p.content,
        '--------------------------------\n',
      );
    }
    if (taskPrompt) {
      parts.push(`<task_instructions>\n${taskPrompt}\n</task_instructions>`);
    }
    return { text: parts.join('\n'), redactions, fileTokens };
  }

  // XML default
  const lines: string[] = [
    '<project_context>',
    `  <source>This file was generated by ptt (ProjectToText) from ${escapeXmlAttr(project.rootName)} (browser mode)</source>`,
    '  <instruction>Below is the complete (curated) content of the project. Use it for code analysis, refactoring, or implementation tasks.</instruction>',
    '  <file_summary>',
    `    Total files included: ${limited.length}`,
    truncatedNote ? `    Note: browser mode capped at ${MAX_PACK_FILES} files` : '',
    '  </file_summary>',
    '  <directory_structure>',
  ].filter(Boolean) as string[];
  // The directory listing stays alphabetical; only the <files> content follows tier order.
  for (const p of [...prepared].sort((a, b) => a.path.localeCompare(b.path))) {
    lines.push(`    ${p.path}`);
  }
  lines.push('  </directory_structure>', '  <files>');
  for (const p of prepared) {
    const safe = p.content.split(']]>').join(']]]]><![CDATA[>');
    const attr = p.isSkel
      ? `path="${escapeXmlAttr(p.path)}" mode="skeleton"`
      : `path="${escapeXmlAttr(p.path)}"`;
    lines.push(
      `    <file ${attr}>`,
      '      <![CDATA[',
      safe,
      '      ]]>',
      '    </file>',
    );
  }
  lines.push('  </files>');
  if (taskPrompt) {
    // Wrapped in CDATA like file contents; `]]>` is split so the section stays well-formed.
    lines.push(
      '  <task_instructions>',
      '      <![CDATA[',
      taskPrompt.split(']]>').join(']]]]><![CDATA[>'),
      '      ]]>',
      '  </task_instructions>',
    );
  }
  lines.push('</project_context>');
  return { text: lines.join('\n'), redactions, fileTokens };
}

export async function generateBrowserOutput(
  project: BrowserProject,
  selectedPaths: string[],
  format: string,
  opts: BrowserGenerateOptions = {},
): Promise<string> {
  const res = await generateBrowserOutputWithStats(project, selectedPaths, format, opts);
  return res.text;
}

export function downloadText(filename: string, text: string) {
  const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

export { isCancelledError };


import { expect, test, type Page } from '@playwright/test';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import ts from 'typescript';

/** Opens a real folder through the app's `<input webkitdirectory>` fallback, as Firefox/Safari users would. */
async function openBrowserFolder(page: Page, dir: string) {
  await page.addInitScript(() => {
    (window as unknown as { showDirectoryPicker?: unknown }).showDirectoryPicker = undefined;
  });
  await page.goto('/');
  const chooser = page.waitForEvent('filechooser');
  await page.getByTestId('btn-open-folder-empty').click();
  await (await chooser).setFiles(dir);
}

function makeFolder(files: Record<string, string>): string {
  const dir = mkdtempSync(join(tmpdir(), 'ptt-badge-'));
  for (const [rel, body] of Object.entries(files)) {
    mkdirSync(dirname(join(dir, rel)), { recursive: true });
    writeFileSync(join(dir, rel), body);
  }
  return dir;
}

test.describe('ProjectToText browser shell', () => {
  test('loads empty state and brand chrome', async ({ page }) => {
    await page.goto('/');

    await expect(page.getByTestId('app-root')).toBeVisible();
    await expect(page.getByTestId('brand')).toContainText('ProjectToText');
    await expect(page.getByTestId('empty-open-project')).toBeVisible();
    await expect(page.getByTestId('empty-open-project')).toContainText('Open a project');
    await expect(page.getByTestId('btn-open-folder')).toBeVisible();
    await expect(page.getByTestId('btn-open-folder-empty')).toBeVisible();
  });

  test('theme toggle cycles without crashing', async ({ page }) => {
    await page.goto('/');
    const themeBtn = page.getByRole('button', { name: /Theme/i });
    await expect(themeBtn).toBeVisible();
    await themeBtn.click();
    await themeBtn.click();
    await expect(page.getByTestId('app-root')).toBeVisible();
    await expect(page.getByTestId('brand')).toContainText('ptt');
  });

  test('folder history panel opens from the header', async ({ page }) => {
    await page.goto('/');
    await page.getByTestId('btn-folder-history').click();
    await expect(page.getByRole('heading', { name: 'Folder history' })).toBeVisible();
    await expect(page.getByText('No folders in history')).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(page.getByRole('heading', { name: 'Folder history' })).toBeHidden();
  });

  test('Escape dismisses custom projects', async ({ page }) => {
    await page.goto('/');
    await page.getByRole('button', { name: 'Open custom projects' }).click();
    await expect(page.getByRole('heading', { name: 'Custom projects' })).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(page.getByRole('heading', { name: 'Custom projects' })).toBeHidden();
  });

  test('browser pack decodes BOM text and preserves Markdown fences', async ({ page }) => {
    await page.goto('/');
    const transpile = (file: string) =>
      ts.transpileModule(readFileSync(file, 'utf8'), {
        compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext },
      }).outputText;
    const source = transpile('src/browserFs.ts');
    const secretsSource = transpile('src/secrets.ts');
    const result = await page.evaluate(async ({ source, secretsSource }) => {
      // browserFs.ts imports ./secrets; load that module from its own blob and point the import at it.
      const secretsUrl = URL.createObjectURL(new Blob([secretsSource], { type: 'text/javascript' }));
      const rewritten = source.replace(/from\s*(["'])\.\/secrets\1/, `from "${secretsUrl}"`);
      const url = URL.createObjectURL(new Blob([rewritten], { type: 'text/javascript' }));
      const { generateBrowserOutput, readBrowserFilePreview } = await import(url);
      URL.revokeObjectURL(url);
      URL.revokeObjectURL(secretsUrl);
      const text = 'Zażółć 😀';
      const bytes = [0xff, 0xfe];
      for (let i = 0; i < text.length; i++) bytes.push(text.charCodeAt(i) & 255, text.charCodeAt(i) >> 8);
      const utf16 = new File([new Uint8Array(bytes)], 'view.xaml');
      const content = '```\n~~~~\n``````\n';
      const project = { rootName: 'fixture', files: new Map([
        ['view.xaml', utf16], ['notes.md', new File([content], 'notes.md')],
      ]) };
      const json = JSON.parse(await generateBrowserOutput(project, ['view.xaml'], 'json'));
      const preview = await readBrowserFilePreview(project, 'view.xaml');
      const markdown = await generateBrowserOutput(project, ['notes.md'], 'markdown');
      return { decoded: json.files[0].content, preview: preview.content, binary: preview.binary, markdown };
    }, { source, secretsSource });
    expect(result.decoded).toBe('Zażółć 😀');
    expect(result.preview).toBe('Zażółć 😀');
    expect(result.binary).toBe(false);
    expect(result.markdown).toContain('\n```````md\n');
  });

  test('browser pack emits source before docs and keeps the directory listing alphabetical', async ({
    page,
  }) => {
    await page.goto('/');
    const transpile = (file: string) =>
      ts.transpileModule(readFileSync(file, 'utf8'), {
        compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext },
      }).outputText;
    const source = transpile('src/browserFs.ts');
    const secretsSource = transpile('src/secrets.ts');
    const xml = await page.evaluate(async ({ source, secretsSource }) => {
      const secretsUrl = URL.createObjectURL(new Blob([secretsSource], { type: 'text/javascript' }));
      const rewritten = source.replace(/from\s*(["'])\.\/secrets\1/, `from "${secretsUrl}"`);
      const url = URL.createObjectURL(new Blob([rewritten], { type: 'text/javascript' }));
      const { generateBrowserOutput } = await import(url);
      URL.revokeObjectURL(url);
      URL.revokeObjectURL(secretsUrl);
      const paths = ['README.md', '.github/workflows/ci.yml', 'src/main.rs', 'tests/smoke.rs', 'Cargo.toml'];
      const project = {
        rootName: 'fixture',
        files: new Map(paths.map((p) => [p, new File([`// ${p}\n`], p.split('/').pop() ?? p)])),
      };
      return generateBrowserOutput(project, paths, 'xml');
    }, { source, secretsSource });
    const filePaths = [...xml.matchAll(/<file path="([^"]+)"/g)].map((m) => m[1]);
    expect(filePaths).toEqual([
      'src/main.rs',
      'Cargo.toml',
      'tests/smoke.rs',
      '.github/workflows/ci.yml',
      'README.md',
    ]);
    const structure = xml.slice(xml.indexOf('<directory_structure>'), xml.indexOf('</directory_structure>'));
    const listed = structure
      .split('\n')
      .map((line) => line.trim())
      .filter((line) => line.includes('/') || line.includes('.'));
    expect(listed).toEqual([
      '.github/workflows/ci.yml',
      'Cargo.toml',
      'README.md',
      'src/main.rs',
      'tests/smoke.rs',
    ]);
  });

  test('help shortcut opens shortcuts dialog', async ({ page }) => {
    await page.goto('/');
    await page.keyboard.press('?');
    // Dialog title from help overlay
    await expect(page.getByText(/keyboard|shortcut|help/i).first()).toBeVisible({
      timeout: 5000,
    });
  });

  test('browser task prompt is masked when redaction is on and counted in the report, like native output', async ({
    page,
  }) => {
    await page.goto('/');
    const transpile = (file: string) =>
      ts.transpileModule(readFileSync(file, 'utf8'), {
        compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext },
      }).outputText;
    const source = transpile('src/browserFs.ts');
    const secretsSource = transpile('src/secrets.ts');
    const token = ['sk-', 'abcdefghijklmnopqrstuvwx'].join('');
    const result = await page.evaluate(
      async ({ source, secretsSource, token }) => {
        const secretsUrl = URL.createObjectURL(new Blob([secretsSource], { type: 'text/javascript' }));
        const rewritten = source.replace(/from\s*(["'])\.\/secrets\1/, `from "${secretsUrl}"`);
        const url = URL.createObjectURL(new Blob([rewritten], { type: 'text/javascript' }));
        const { generateBrowserOutputWithStats } = await import(url);
        URL.revokeObjectURL(url);
        URL.revokeObjectURL(secretsUrl);

        const project = {
          rootName: 'fixture',
          files: new Map<string, File>([['src/main.rs', new File(['fn main() {}\n'], 'main.rs')]]),
        };
        const prompt = `Why does this key fail: ${token} ?`;
        const masked = await generateBrowserOutputWithStats(project, ['src/main.rs'], 'xml', {
          redactSecrets: true,
          taskPrompt: prompt,
        });
        const verbatim = await generateBrowserOutputWithStats(project, ['src/main.rs'], 'xml', {
          redactSecrets: false,
          taskPrompt: prompt,
        });
        return {
          maskedText: masked.text as string,
          maskedCount: masked.redactions.totalRedactions as number,
          verbatimText: verbatim.text as string,
        };
      },
      { source, secretsSource, token },
    );
    expect(result.maskedText).not.toContain(token);
    expect(result.maskedText).toContain('[REDACTED: OPENAI_API_KEY]');
    expect(result.maskedCount).toBeGreaterThanOrEqual(1);
    expect(result.verbatimText).toContain(token);
  });

  test('browser ignore semantics match native .gitignore and .pttignore fixtures (nested rules, negation, parent pruning, fail-closed)', async ({
    page,
  }) => {
    await page.goto('/');
    const transpile = (file: string) =>
      ts.transpileModule(readFileSync(file, 'utf8'), {
        compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext },
      }).outputText;
    const source = transpile('src/browserFs.ts');
    const secretsSource = transpile('src/secrets.ts');
    const result = await page.evaluate(async ({ source, secretsSource }) => {
      const secretsUrl = URL.createObjectURL(new Blob([secretsSource], { type: 'text/javascript' }));
      const rewritten = source.replace(/from\s*(["'])\.\/secrets\1/, `from "${secretsUrl}"`);
      const url = URL.createObjectURL(new Blob([rewritten], { type: 'text/javascript' }));
      const { applyIgnoreSemanticsToFileMap } = await import(url);
      URL.revokeObjectURL(url);
      URL.revokeObjectURL(secretsUrl);

      // Fixture 1: nested_rules_match_git_and_fallback_with_parent_pruning + .gitignore
      const raw1 = new Map<string, File>([
        ['.gitignore', new File(['secret.env\n'], '.gitignore')],
        ['.pttignore', new File(['*.log\nblocked/\n'], '.pttignore')],
        ['src/.pttignore', new File(['!keep.log\nprivate/\n!private/key.txt\n'], '.pttignore')],
        ['src/keep.log', new File(['fixture'], 'keep.log')],
        ['src/noise.log', new File(['fixture'], 'noise.log')],
        ['src/private/key.txt', new File(['fixture'], 'key.txt')],
        ['blocked/key.txt', new File(['fixture'], 'key.txt')],
        ['secret.env', new File(['KEY=1'], 'secret.env')],
        ['normal.rs', new File(['fixture'], 'normal.rs')],
      ]);
      const res1 = await applyIgnoreSemanticsToFileMap(raw1);
      const kept1 = Array.from(res1.files.keys()).sort();

      // Fixture 2: malformed foreign .gitignore does NOT abort walk
      const raw2 = new Map<string, File>([
        ['sub/.gitignore', new File(['[\n\\\n**[\n!\n'], '.gitignore')],
        ['sub/ok.txt', new File(['ok'], 'ok.txt')],
      ]);
      const res2 = await applyIgnoreSemanticsToFileMap(raw2);
      const kept2 = Array.from(res2.files.keys()).sort();

      // Fixture 3: malformed .pttignore fails closed
      let pttFailedClosed = false;
      try {
        const raw3 = new Map<string, File>([
          ['.pttignore', new File(['\\\n'], '.pttignore')],
          ['ok.txt', new File(['ok'], 'ok.txt')],
        ]);
        await applyIgnoreSemanticsToFileMap(raw3);
      } catch {
        pttFailedClosed = true;
      }

      return {
        kept1,
        skippedReasons: res1.skipped.map((s: { path: string; reason: string }) => `${s.path}:${s.reason}`).sort(),
        kept2,
        pttFailedClosed,
      };
    }, { source, secretsSource });

    expect(result.kept1).toEqual([
      '.gitignore',
      '.pttignore',
      'normal.rs',
      'src/.pttignore',
      'src/keep.log',
    ]);
    expect(result.skippedReasons).toContain('blocked:pttignore');
    expect(result.skippedReasons).toContain('src/private:pttignore');
    expect(result.skippedReasons).toContain('src/noise.log:pttignore');
    expect(result.skippedReasons).toContain('secret.env:gitignore');
    expect(result.kept2).toEqual(['sub/.gitignore', 'sub/ok.txt']);
    expect(result.pttFailedClosed).toBe(true);
  });

  test('redaction badge shows scanned and skipped counts for a clean folder and a folder with a secret', async ({
    page,
  }) => {
    const token = ['sk-', 'abcdefghijklmnopqrstuvwx'].join('');
    const clean = makeFolder({ 'src/main.rs': 'fn main() {}\n', 'README.md': '# demo\n' });
    const dirty = makeFolder({ 'src/main.rs': `const KEY = "${token}";\n`, 'README.md': '# demo\n' });
    try {
      const badge = page.getByTestId('redaction-badge');

      await openBrowserFolder(page, clean);
      await expect(badge).toContainText('0 secrets masked');
      await expect(badge).toContainText('2 scanned');
      await expect(badge).toContainText('0 skipped');

      await openBrowserFolder(page, dirty);
      await expect(badge).toContainText('1 secrets masked');
      await expect(badge).toContainText('2 scanned');
      await expect(badge).toContainText('0 skipped');
    } finally {
      rmSync(clean, { recursive: true, force: true });
      rmSync(dirty, { recursive: true, force: true });
    }
  });
});
